let currentImageUrl = null;
let currentWorkerUrl = null;
const fbUrlInput = document.getElementById('fbUrlInput'),
  downloadForm = document.getElementById('downloadForm'),
  submitBtn = document.getElementById('submitBtn'),
  btnText = document.getElementById('btnText'),
  btnLoader = document.getElementById('btnLoader'),
  loadingBox = document.getElementById('loadingBox'),
  errorMessage = document.getElementById('errorMessage'),
  errorText = document.getElementById('errorText'),
  resultSection = document.getElementById('resultSection'),
  profilePreview = document.getElementById('profilePreview'),
  copyUrlBtn = document.getElementById('copyUrlBtn'),
  directDownloadBtn = document.getElementById('directDownloadBtn');

const WORKER_URLS = [
  'https://fbdp.romitkryadav.workers.dev/',
  'https://fbdp1.romitkr5539.workers.dev/',
  'https://fbdp3.romitkr3018.workers.dev/',
  'https://fbdp4.ronitkr9341.workers.dev/',
];

function fetchWithTimeout(url, timeout = 10000) {
  return Promise.race([
    fetch(url),
    new Promise((_, reject) => setTimeout(() => reject(new Error('Request timeout')), timeout)),
  ]);
}

async function queryWorker(workerUrl, url) {
  const apiUrl = `${workerUrl.replace(/\/$/, '')}/?url=${encodeURIComponent(url)}`;
  const response = await fetchWithTimeout(apiUrl, 15000);
  const data = await response.json().catch(() => ({ success: false, error: 'Failed to parse server response' }));
  if (!response.ok || data.success === false) {
    throw new Error(data.error || 'Profile picture not found. It might be private.');
  }
  const imageUrl = data.imageUrl || data.hd || data.sd;
  if (!imageUrl) throw new Error('Could not find image URL in the response.');
  return { workerUrl, imageUrl };
}

function triggerAnchorToHiddenIframe(url) {
  try {
    let iframe = document.getElementById('__dlIframe');
    if (!iframe) {
      iframe = document.createElement('iframe');
      iframe.id = '__dlIframe';
      iframe.name = '__dlIframe';
      iframe.style.display = 'none';
      iframe.style.width = '0';
      iframe.style.height = '0';
      iframe.style.border = '0';
      iframe.setAttribute('sandbox', 'allow-downloads allow-same-origin allow-scripts allow-popups');
      document.body.appendChild(iframe);
    }
    const a = document.createElement('a');
    a.href = url;
    a.target = '__dlIframe';
    a.rel = 'noopener';
    a.setAttribute('referrerpolicy', 'no-referrer');
    document.body.appendChild(a);
    a.click();
    a.remove();
  } catch (_) {}
}

function saveViaAnchor(imageUrl, filename) {
  return new Promise((resolve) => {
    try {
      const a = document.createElement('a');
      a.href = imageUrl;
      a.download = filename;
      a.rel = 'noopener';
      a.setAttribute('referrerpolicy', 'no-referrer');
      document.body.appendChild(a);
      a.click();
      setTimeout(() => { a.remove(); resolve(true); }, 0);
    } catch (e) { resolve(false); }
  });
}

async function downloadImageBlob(imageUrl, filename) {
  // 1) Try fetch CORS
  try {
    const r = await fetch(imageUrl, { credentials: 'omit', referrerPolicy: 'no-referrer', mode: 'cors' });
    if (r.ok) {
      const blob = await r.blob();
      if (blob && blob.size > 0) {
        const u = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = u; a.download = filename;
        document.body.appendChild(a); a.click(); a.remove();
        setTimeout(() => URL.revokeObjectURL(u), 3000);
        return true;
      }
    }
  } catch (_) {}

  // 2) Try fetch NO-CORS (opaque blob — browser can still download via native a.download
  try {
    const r2 = await fetch(imageUrl, { credentials: 'omit', referrerPolicy: 'no-referrer', mode: 'no-cors' });
    // .blob() on opaque response should succeed; file bytes are there for the browser's native save
    const blob2 = await r2.blob();
    if (blob2) {
      const u2 = URL.createObjectURL(blob2);
      const a2 = document.createElement('a');
      a2.href = u2; a2.download = filename;
      document.body.appendChild(a2); a2.click(); a2.remove();
      setTimeout(() => URL.revokeObjectURL(u2), 3000);
      return true;
    }
  } catch (_) {}

  return false;
}

async function handleDownload(e) {
  e.preventDefault();
  let url = fbUrlInput ? fbUrlInput.value.trim() : '';
  if (!url) {
    showError('Please paste a Facebook URL first');
    return;
  }
  currentImageUrl = null;
  currentWorkerUrl = null;
  if (!url.startsWith('http')) url = 'https://' + url;
  setLoading(true);
  hideError();
  if (resultSection) { resultSection.classList.add('hidden'); resultSection.classList.remove('active'); }

  try {
    const attempts = WORKER_URLS.map(w => queryWorker(w, url));
    const { workerUrl, imageUrl } = await Promise.any(attempts);

    currentImageUrl = imageUrl;
    currentWorkerUrl = workerUrl;

    // Wrap preview <img> in a clickable download anchor
    if (profilePreview) {
      profilePreview.src = imageUrl;
      profilePreview.setAttribute('referrerpolicy', 'no-referrer');
      profilePreview.style.cursor = 'pointer';
      profilePreview.title = 'Click to save image';
      profilePreview.onclick = () => {
        if (!currentImageUrl) return;
        const fn = `fb-dp-click-${Date.now()}.jpg`;
        downloadImageBlob(currentImageUrl, fn).then((ok) => {
          if (!ok) saveViaAnchor(currentImageUrl, fn);
        });
      };
    }

    if (resultSection) {
      resultSection.classList.remove('hidden');
      resultSection.classList.add('active');
      setTimeout(() => resultSection.scrollIntoView({ behavior: 'smooth', block: 'center' }), 50);
    }
  } catch (err) {
    const message = err.errors?.length
      ? err.errors[err.errors.length - 1].message
      : (err.message || 'All servers failed. Please try again.');
    if (err.name !== 'AbortError') showError(message);
  } finally {
    setLoading(false);
  }
}

async function handleDirectDownload() {
  if (!currentImageUrl || !directDownloadBtn) return;
  const btnContent = directDownloadBtn.innerHTML;
  try {
    directDownloadBtn.disabled = true;
    directDownloadBtn.textContent = 'Downloading...';
    const filename = `fb-dp-${Date.now()}.jpg`;

    const ok = await downloadImageBlob(currentImageUrl, filename);

    if (!ok) {
      // Fallback A: hidden iframe anchor with no-referrer
      triggerAnchorToHiddenIframe(currentImageUrl);
      // Fallback B (parallel safety): plain anchor — no target (no new tab)
      // If download attr is honored → direct save, else → same-tab image display (no error page)
      saveViaAnchor(currentImageUrl, filename);
    }

    setTimeout(() => {
      directDownloadBtn.innerHTML = btnContent;
      directDownloadBtn.disabled = false;
    }, 2000);
  } catch (l) {
    try { saveViaAnchor(currentImageUrl, `fb-dp-${Date.now()}.jpg`); } catch (_) {}
    directDownloadBtn.innerHTML = btnContent;
    directDownloadBtn.disabled = false;
  }
}

function copyImageUrl() {
  if (!currentImageUrl || !copyUrlBtn) return;
  const btnContent = copyUrlBtn.innerHTML;
  const done = () => {
    copyUrlBtn.innerHTML = '<svg width="18" height="18" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M8 5H6a2 2 0 00-2 2v12a2 2 0 002 2h10a2 2 0 002-2v-1M8 5a2 2 0 002 2h2a2 2 0 002-2M8 5a2 2 0 012-2h2a2 2 0 012 2m0 0h2a2 2 0 012 2v3m2 4H10m0 0l3-3m-3 3l3 3"></path></svg>Copied!';
    setTimeout(() => copyUrlBtn.innerHTML = btnContent, 2000);
  };
  const fallbackCopy = () => {
    try {
      const ta = document.createElement('textarea');
      ta.value = currentImageUrl;
      ta.style.position = 'fixed';
      ta.style.top = '-9999px';
      document.body.appendChild(ta);
      ta.select();
      try { document.execCommand('copy'); done(); } catch (_) { done(); }
      setTimeout(() => document.body.removeChild(ta), 0);
    } catch (_) { done(); }
  };
  if (navigator.clipboard && navigator.clipboard.writeText) {
    navigator.clipboard.writeText(currentImageUrl).then(done).catch(fallbackCopy);
  } else fallbackCopy();
}

function setLoading(isLoading) {
  if (submitBtn && btnText && btnLoader) {
    if (isLoading) {
      submitBtn.disabled = true;
      btnText.classList.add('hidden');
      btnLoader.classList.remove('hidden');
    } else {
      submitBtn.disabled = false;
      btnText.classList.remove('hidden');
      btnLoader.classList.add('hidden');
    }
  }
  if (loadingBox) {
    if (isLoading) {
      loadingBox.hidden = false;
      loadingBox.classList.remove('hidden');
      loadingBox.classList.add('active');
    } else {
      loadingBox.hidden = true;
      loadingBox.classList.add('hidden');
      loadingBox.classList.remove('active');
    }
  }
}

function showError(msg) {
  if (errorMessage && errorText) {
    errorText.textContent = msg;
    errorMessage.classList.remove('hidden');
    errorMessage.classList.add('active');
  }
}

function hideError() {
  if (errorMessage) {
    errorMessage.classList.add('hidden');
    errorMessage.classList.remove('active');
  }
}

if (downloadForm) downloadForm.addEventListener('submit', handleDownload);
if (copyUrlBtn) copyUrlBtn.addEventListener('click', copyImageUrl);
if (directDownloadBtn) directDownloadBtn.addEventListener('click', handleDirectDownload);





